using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Collections.Immutable;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Threading.Tasks;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Diagnostics;

public class A5_F2_AnalyzerClosedGenericStructFromMetadataTests
{
    private const string AnnotatedLibrarySource = """
using MessagePack;

namespace RefLib
{
    [MessagePackObject]
    public struct GenericStruct<T>
    {
        [Key(0)]
        public T Value { get; set; }
    }

    [MessagePackObject]
    public struct GenericStruct2<T1, T2>
    {
        [Key(0)]
        public T1 A { get; set; }

        [Key(1)]
        public T2 B { get; set; }
    }

    [MessagePackObject]
    public record struct GenericRecordStruct<T1, T2>([property: Key(0)] T1 A, [property: Key(1)] T2 B);
}
""";

    private const string AnnotatedUsageSource = """
using MessagePack;
using RefLib;

namespace TempProject
{
    [MessagePackObject]
    public class MyObject
    {
        [Key(0)]
        public GenericStruct<int> A { get; set; }

        [Key(1)]
        public GenericStruct2<string, long> B { get; set; }

        [Key(2)]
        public GenericRecordStruct<int, string> C { get; set; }

        [Key(3)]
        public GenericStruct<GenericStruct<int>> D { get; set; }
    }
}
""";

    private const string PlainLibrarySource = """
namespace RefLib
{
    public struct PlainGenericStruct<T>
    {
        public T Value { get; set; }
    }

    public record struct PlainGenericRecordStruct<T1, T2>(T1 A, T2 B);
}
""";

    private const string PlainUsageSource = """
using MessagePack;
using RefLib;

namespace TempProject
{
    [MessagePackObject]
    public class MyObject
    {
        [Key(0)]
        public PlainGenericStruct<int> A { get; set; }

        [Key(1)]
        public PlainGenericRecordStruct<string, long> B { get; set; }
    }
}
""";

    [Fact]
    public async Task A5_F2_Analyzer_DoesNotCrash_OnAnnotatedClosedGenericStructFromMetadata()
    {
        await RunAndAssertNoCrashAsync(AnnotatedLibrarySource, AnnotatedUsageSource);
    }

    [Fact]
    public async Task A5_F2_Analyzer_DoesNotCrash_OnPlainClosedGenericStructFromMetadata()
    {
        await RunAndAssertNoCrashAsync(PlainLibrarySource, PlainUsageSource);
    }

    private static async Task RunAndAssertNoCrashAsync(string librarySource, string usageSource)
    {
        CSharpParseOptions parseOptions = new CSharpParseOptions(LanguageVersion.CSharp10);
        List<MetadataReference> baseReferences = GetBaseReferences();

        CSharpCompilation library = CSharpCompilation.Create(
            "RefLib",
            new[] { CSharpSyntaxTree.ParseText(librarySource, parseOptions) },
            baseReferences,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        Assert.NotNull(library.GetTypeByMetadataName("MessagePack.MessagePackObjectAttribute"));

        byte[] image;
        using (MemoryStream ms = new MemoryStream())
        {
            var emitResult = library.Emit(ms);
            Assert.True(
                emitResult.Success,
                "Library failed to compile: " + string.Join(Environment.NewLine, emitResult.Diagnostics.Where(d => d.Severity == DiagnosticSeverity.Error)));
            image = ms.ToArray();
        }

        List<MetadataReference> references = new List<MetadataReference>(baseReferences)
        {
            MetadataReference.CreateFromImage(image),
        };

        CSharpCompilation compilation = CSharpCompilation.Create(
            "TempProject",
            new[] { CSharpSyntaxTree.ParseText(usageSource, parseOptions) },
            references,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        var compileErrors = compilation.GetDiagnostics().Where(d => d.Severity == DiagnosticSeverity.Error).ToList();
        Assert.True(compileErrors.Count == 0, "Usage failed to compile: " + string.Join(Environment.NewLine, compileErrors));

        ImmutableArray<DiagnosticAnalyzer> analyzers = DiscoverAnalyzers();
        Assert.False(analyzers.IsEmpty, "No MessagePack analyzers were found.");

        ConcurrentBag<string> exceptions = new ConcurrentBag<string>();
        CompilationWithAnalyzersOptions options = new CompilationWithAnalyzersOptions(
            new AnalyzerOptions(ImmutableArray<AdditionalText>.Empty),
            (ex, analyzer, diag) => exceptions.Add(analyzer.GetType().FullName + ": " + ex),
            concurrentAnalysis: false,
            logAnalyzerExecutionTime: false);

        CompilationWithAnalyzers withAnalyzers = compilation.WithAnalyzers(analyzers, options);
        ImmutableArray<Diagnostic> diagnostics = await withAnalyzers.GetAnalyzerDiagnosticsAsync();

        Assert.True(exceptions.IsEmpty, "Analyzer threw: " + string.Join(Environment.NewLine, exceptions));

        var crashDiagnostics = diagnostics.Where(d => d.Id == "AD0001").ToList();
        Assert.True(crashDiagnostics.Count == 0, "AD0001 reported: " + string.Join(Environment.NewLine, crashDiagnostics));
        Assert.DoesNotContain(diagnostics, d => d.GetMessage().Contains("IndexOutOfRangeException"));
    }

    private static ImmutableArray<DiagnosticAnalyzer> DiscoverAnalyzers()
    {
        HashSet<Assembly> assemblies = new HashSet<Assembly>
        {
            typeof(MessagePack.SourceGenerator.MessagePackGenerator).Assembly,
        };
        foreach (Assembly asm in AppDomain.CurrentDomain.GetAssemblies())
        {
            string? name = asm.GetName().Name;
            if (!asm.IsDynamic && name is not null && name.StartsWith("MessagePack", StringComparison.Ordinal) && name.Contains("Analyzer"))
            {
                assemblies.Add(asm);
            }
        }

        List<DiagnosticAnalyzer> result = new List<DiagnosticAnalyzer>();
        HashSet<Type> seen = new HashSet<Type>();
        foreach (Assembly asm in assemblies)
        {
            Type[] types;
            try
            {
                types = asm.GetTypes();
            }
            catch (ReflectionTypeLoadException ex)
            {
                types = ex.Types.Where(t => t is not null).Select(t => t!).ToArray();
            }

            foreach (Type t in types)
            {
                if (!t.IsAbstract
                    && typeof(DiagnosticAnalyzer).IsAssignableFrom(t)
                    && t.GetCustomAttributes(typeof(DiagnosticAnalyzerAttribute), false).Length > 0
                    && t.GetConstructor(Type.EmptyTypes) is not null
                    && seen.Add(t))
                {
                    result.Add((DiagnosticAnalyzer)Activator.CreateInstance(t)!);
                }
            }
        }

        return result.ToImmutableArray();
    }

    private static List<MetadataReference> GetBaseReferences()
    {
        foreach (string name in new[] { "MessagePack.Annotations", "MessagePack" })
        {
            try
            {
                Assembly.Load(new AssemblyName(name));
            }
            catch
            {
                // ignore; resolution is asserted later.
            }
        }

        Dictionary<string, MetadataReference> refs = new Dictionary<string, MetadataReference>(StringComparer.OrdinalIgnoreCase);
        if (AppContext.GetData("TRUSTED_PLATFORM_ASSEMBLIES") is string tpa)
        {
            foreach (string path in tpa.Split(Path.PathSeparator))
            {
                if (path.EndsWith(".dll", StringComparison.OrdinalIgnoreCase) && File.Exists(path))
                {
                    string key = Path.GetFileNameWithoutExtension(path);
                    if (!refs.ContainsKey(key))
                    {
                        refs[key] = MetadataReference.CreateFromFile(path);
                    }
                }
            }
        }

        foreach (Assembly asm in AppDomain.CurrentDomain.GetAssemblies())
        {
            if (asm.IsDynamic || string.IsNullOrEmpty(asm.Location))
            {
                continue;
            }

            string key = Path.GetFileNameWithoutExtension(asm.Location);
            if (!refs.ContainsKey(key))
            {
                refs[key] = MetadataReference.CreateFromFile(asm.Location);
            }
        }

        return refs.Values.ToList();
    }
}
